"""Read the bank export into (date, category, amount) tuples."""
import csv

from money import parse_amount


def parse_rows(text):
    lines = text.split("\n")[1:-1]  # drop the header and the empty string after the final newline
    out = []
    for row in csv.reader(lines):
        if not row:
            continue
        date, category, amount = row
        out.append((date.strip(), category.strip(), parse_amount(amount)))
    return out


def import_file(path):
    with open(path, encoding="utf-8") as f:
        return parse_rows(f.read())

