"""Totals per category and their display."""
from collections import defaultdict
from decimal import ROUND_HALF_UP, Decimal


def totals_by_category(rows):
    totals = defaultdict(Decimal)
    for _date, category, amount in rows:
        totals[category] += amount
    return dict(totals)


def format_amount(value):
    cents = Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if cents == 0:
        cents = abs(cents)
    return f"{cents:,.2f}"


def render(rows):
    lines = []
    for category, total in sorted(totals_by_category(rows).items()):
        lines.append(f"{category:<14}{format_amount(total):>14}")
    return "\n".join(lines)

