"""Payments worker: applies a batch of instructions using a thread pool."""
from concurrent.futures import ThreadPoolExecutor

from accounts import InsufficientFunds


def apply_instruction(bank, instr):
    kind = instr["kind"]
    if kind == "deposit":
        bank.accounts[instr["account"]].deposit(instr["amount"])
    elif kind == "withdraw":
        bank.accounts[instr["account"]].withdraw(instr["amount"])
    elif kind == "transfer":
        bank.transfer(instr["src"], instr["dst"], instr["amount"])
    else:
        raise ValueError(f"unknown instruction {kind!r}")


def run_batch(bank, instructions, threads=8):
    """Apply all instructions; return the list of instructions that were rejected."""
    rejected = []

    def one(instr):
        try:
            apply_instruction(bank, instr)
        except InsufficientFunds:
            rejected.append(instr)

    with ThreadPoolExecutor(max_workers=threads) as pool:
        list(pool.map(one, instructions))
    return rejected

