import audit
from accounts import Account


class Bank:
    def __init__(self):
        self.accounts = {}

    def open(self, account_id, balance=0):
        if account_id in self.accounts:
            raise ValueError(f"account {account_id!r} exists")
        self.accounts[account_id] = Account(account_id, balance)
        return self.accounts[account_id]

    def balance(self, account_id):
        return self.accounts[account_id].balance

    def transfer(self, src_id, dst_id, amount):
        src = self.accounts[src_id]
        dst = self.accounts[dst_id]
        if src_id == dst_id:
            raise ValueError("cannot transfer to the same account")
        if amount <= 0:
            raise ValueError("amount must be positive")
        # Always lock in the same global order to avoid deadlock.
        first, second = sorted((src, dst), key=lambda a: repr(a.id))
        with first.lock:
            with second.lock:
                audit.record("transfer-start", src=src_id, dst=dst_id, amount=amount)
                src.withdraw(amount)  # raises before anything changed if short
                dst.deposit(amount)

    def total(self):
        return sum(a.balance for a in self.accounts.values())

