"""Tiny search over one document: find windows that contain every query word."""
import re

from chunker import chunks
from pager import page_info

WINDOW = 8
OVERLAP = 3


def tokenize(text):
    return re.findall(r"\w+", text.lower())


def find_windows(text, query):
    words = set(tokenize(query))
    hits = []
    for window in chunks(tokenize(text), WINDOW, OVERLAP):
        if words and words <= set(window):
            hits.append(" ".join(window))
    return hits


def search_page(text, query, page=1, per_page=5):
    hits = find_windows(text, query)
    info = page_info(len(hits), page, per_page)
    return {"label": info["label"], "pages": info["pages"],
            "results": hits[info["start"]:info["end"]]}


if __name__ == "__main__":
    import sys
    with open(sys.argv[1], encoding="utf-8") as f:
        doc = f.read()
    res = search_page(doc, " ".join(sys.argv[2:]))
    print(res["label"])
    for r in res["results"]:
        print(" -", r)

