import unittest

from chunker import chunks
from pager import page_info


def expected_chunks(items, size, overlap):
    out, start, step = [], 0, size - overlap
    while start < len(items):
        out.append(list(items[start:start + size]))
        if start + size >= len(items):
            break
        start += step
    return out


class TestChunks(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(chunks(list(range(10)), 4, 2), [[0, 1, 2, 3], [2, 3, 4, 5], [4, 5, 6, 7], [6, 7, 8, 9]])
        self.assertEqual(chunks(list(range(9)), 4, 2), [[0, 1, 2, 3], [2, 3, 4, 5], [4, 5, 6, 7], [6, 7, 8]])
        self.assertEqual(chunks("abcde", 5, 1), [list("abcde")])
        self.assertEqual(chunks((), 3, 1), [])

    def test_invalid(self):
        for size, overlap in [(0, 0), (3, 3), (3, 5), (3, -1)]:
            with self.assertRaises(ValueError):
                chunks([1, 2, 3, 4], size, overlap)

    def test_properties_exhaustive(self):
        for n in range(0, 26):
            items = list(range(n))
            for size in range(1, 9):
                for overlap in range(0, size):
                    got = chunks(items, size, overlap)
                    self.assertEqual(got, expected_chunks(items, size, overlap), (n, size, overlap))
                    if n:
                        self.assertEqual(got[-1][-1], n - 1)
                        self.assertTrue(all(len(c) == size for c in got[:-1]))
                        for a, b in zip(got, got[1:]):
                            self.assertGreater(b[-1], a[-1])


class TestPager(unittest.TestCase):
    def test_middle_and_last(self):
        self.assertEqual(page_info(23, 2, 10), {"pages": 3, "start": 10, "end": 20, "label": "Showing 11–20 of 23"})
        self.assertEqual(page_info(23, 3, 10), {"pages": 3, "start": 20, "end": 23, "label": "Showing 21–23 of 23"})

    def test_exact_multiple(self):
        self.assertEqual(page_info(20, 2, 10)["pages"], 2)
        with self.assertRaises(ValueError):
            page_info(20, 3, 10)

    def test_empty_and_single(self):
        self.assertEqual(page_info(0, 1, 10), {"pages": 1, "start": 0, "end": 0, "label": "No results"})
        self.assertEqual(page_info(1, 1, 10)["label"], "Showing 1–1 of 1")
        self.assertEqual(page_info(7, 7, 1)["label"], "Showing 7–7 of 7")

    def test_invalid(self):
        for args in [(5, 0, 10), (5, 2, 10), (5, 1, 0), (-1, 1, 10), (0, 2, 10)]:
            with self.assertRaises(ValueError):
                page_info(*args)

    def test_slices_cover_everything_once(self):
        for total in range(0, 40):
            for per in range(1, 12):
                seen = []
                pages = page_info(total, 1, per)["pages"]
                for p in range(1, pages + 1):
                    info = page_info(total, p, per)
                    self.assertLessEqual(info["end"], total)
                    seen.extend(range(info["start"], info["end"]))
                self.assertEqual(seen, list(range(total)), (total, per))


if __name__ == "__main__":
    unittest.main()

