"""Paging through a result list. See README.md."""


def page_info(total, page, per_page):
    if per_page < 1 or total < 0:
        raise ValueError("per_page must be >= 1 and total >= 0")
    pages = max(1, -(-total // per_page))
    if page < 1 or page > pages:
        raise ValueError(f"page {page} out of range 1..{pages}")
    start = min((page - 1) * per_page, total)
    end = min(start + per_page, total)
    label = "No results" if total == 0 else f"Showing {start + 1}–{end} of {total}"
    return {"pages": pages, "start": start, "end": end, "label": label}

