from textwidth import truncate


def render(rows, max_width=12):
    if not rows:
        return ""
    cells = [[truncate(str(c), max_width) for c in row] for row in rows]
    ncols = max(len(r) for r in cells)
    cells = [r + [""] * (ncols - len(r)) for r in cells]
    widths = [max(len(r[i]) for r in cells) for i in range(ncols)]
