"""Terminal display width helpers. See README.md."""
import unicodedata

ELLIPSIS = "…"


def char_width(ch):
    if unicodedata.category(ch) in ("Mn", "Me", "Cf"):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1


def display_width(s):
    return sum(char_width(ch) for ch in s)


def clusters(s):
    """Split s into a base character plus the zero-width characters that follow it."""
    out = []
    for ch in s:
        if out and char_width(ch) == 0:
            out[-1] += ch
        else:
            out.append(ch)
    return out


def truncate(s, width):
    if width < 1:
        raise ValueError("width must be >= 1")
    if display_width(s) <= width:
        return s
    kept, used = [], 0
    for cl in clusters(s):
        w = display_width(cl)
        if used + w > width - 1:
            break
        kept.append(cl)
        used += w
    return "".join(kept) + ELLIPSIS


def pad(s, width):
    return s + " " * max(0, width - display_width(s))

