from datetime import timezone


def elapsed(a, b):
    if a.utcoffset() is None or b.utcoffset() is None:
        raise ValueError("naive datetime")
    # Subtracting two datetimes that share a tzinfo compares wall clocks, so go through UTC.
    return b.astimezone(timezone.utc) - a.astimezone(timezone.utc)


def total_hours(shifts):
    total = 0.0
    for start, end in shifts:
        total += elapsed(start, end).total_seconds() / 3600
    return total

