"""Summarise readings from several collectors.

Usage: python summary.py FILE...   (one reading per line in each file, one file per collector)
"""
import sys

from frange import frange
from percentile import percentile
from running import RunningStats


def load(path):
    with open(path, encoding="utf-8") as f:
        return [float(line) for line in f if line.strip()]


def histogram(values, lo, hi, width):
    edges = frange(lo, hi, width)
    counts = [0] * len(edges)
    for v in values:
        for i, e in enumerate(edges):
            if e <= v < e + width:
                counts[i] += 1
                break
    return list(zip(edges, counts))


def main(paths):
    merged = RunningStats()
    everything = []
    for p in paths:
        values = load(p)
        st = RunningStats()
        for v in values:
            st.add(v)
        merged = merged.merge(st)
        everything.extend(values)
    print(f"n={merged.count} mean={merged.mean:.6f} sd={merged.stdev:.6f}")
    print(f"p50={percentile(everything, 50):.6f} p95={percentile(everything, 95):.6f}")
    for edge, n in histogram(everything, merged.min, merged.max + 1e-9, (merged.max - merged.min) / 5 or 1):
        print(f"{edge:>20.6f} {'#' * n}")


if __name__ == "__main__":
    main(sys.argv[1:])

