"""Percentiles. See README.md."""
import math


def percentile(data, p):
    if not 0 <= p <= 100:
        raise ValueError("p must be between 0 and 100")
    s = sorted(data)
    if not s:
        raise ValueError("no data")
    pos = (len(s) - 1) * p / 100
    lo = math.floor(pos)
    hi = min(lo + 1, len(s) - 1)
    return s[lo] + (s[hi] - s[lo]) * (pos - lo)

