"""Streaming statistics (Welford update, Chan et al. merge). See README.md."""
import math


class RunningStats:
    def __init__(self):
        self.count = 0
        self._mean = 0.0
        self._m2 = 0.0  # sum of squared deviations from the mean
        self.min = None
        self.max = None

    def add(self, x):
        self.count += 1
        delta = x - self._mean
        self._mean += delta / self.count
        self._m2 += delta * (x - self._mean)
        self.min = x if self.min is None else min(self.min, x)
        self.max = x if self.max is None else max(self.max, x)

    @property
    def mean(self):
        if self.count == 0:
            raise ValueError("no values")
        return self._mean

    @property
    def variance(self):
        if self.count < 2:
            return 0.0
        return max(0.0, self._m2 / (self.count - 1))

    @property
    def stdev(self):
        return math.sqrt(self.variance)

    def merge(self, other):
        out = RunningStats()
        n = self.count + other.count
        out.count = n
        if n:
            delta = other._mean - self._mean
            out._mean = self._mean + delta * other.count / n
            out._m2 = self._m2 + other._m2 + delta * delta * self.count * other.count / n
        mins = [m for m in (self.min, other.min) if m is not None]
        maxs = [m for m in (self.max, other.max) if m is not None]
        out.min = min(mins) if mins else None
        out.max = max(maxs) if maxs else None
        return out

