from legacy_query import parse_qs_legacy


def search_handler(url_query):
    q = parse_qs_legacy(url_query)
    terms = q.get("q", "")
    if isinstance(terms, list):
        terms = " ".join(terms)
    tags = q.get("tag", [])
    if isinstance(tags, str):
        tags = [tags]
    page = q.get("page", "1")
    if isinstance(page, list):
        page = page[-1]
    try:
        page = max(1, int(page))
    except ValueError:
        page = 1
    return {"terms": terms.strip(), "tags": sorted(set(tags)), "page": page}


def unsubscribe_handler(url_query):
    q = parse_qs_legacy(url_query)
    email = q.get("email")
    if not isinstance(email, str) or "@" not in email:
        return {"status": 400}
    return {"status": 200, "email": email}

