"""Query-string parsing, written in 2014. Everything in app.py depends on its exact behaviour,
including the odd cases, so it must not change."""

HEXDIGITS = "0123456789abcdefABCDEF"


def _decode(t):
    buf = bytearray()
    i = 0
    while i < len(t):
        c = t[i]
        if c == "+":
            buf.append(32)
            i = i + 1
        elif c == "%" and i + 2 < len(t) and t[i + 1] in HEXDIGITS and t[i + 2] in HEXDIGITS:
            buf.append(int(t[i + 1] + t[i + 2], 16))
            i = i + 3
        else:
            for b in c.encode("utf-8"):
                buf.append(b)
            i = i + 1
    return buf.decode("utf-8", "replace")


def parse_qs_legacy(s):
    result = {}
    if s is None:
        return result
    s = str(s)
    if s.startswith("?"):
        s = s[1:]
    segs = []
    cur = ""
    for ch in s:
        if ch == "&" or ch == ";":
            segs.append(cur)
            cur = ""
        else:
            cur = cur + ch
    segs.append(cur)
