"""Conflict checks. See README.md. Correct, but far too slow for a year of data."""
from bookings import valid


def _clash(a, b):
    return a.room == b.room and a.start < b.end and b.start < a.end


def count_conflicts(bookings):
    items = [b for b in bookings if valid(b)]
    n = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if _clash(items[i], items[j]):
                n += 1
    return n


def max_concurrent(bookings, room):
    items = [b for b in bookings if valid(b) and b.room == room]
    if not items:
        return 0
    best = 0
    for t in range(min(b.start for b in items), max(b.end for b in items)):
        best = max(best, sum(1 for b in items if b.start <= t < b.end))
    return best


def conflicts_by_room(bookings):
    rooms = sorted({b.room for b in bookings})
    out = {}
    for r in rooms:
        c = count_conflicts([b for b in bookings if b.room == r])
        if c:
            out[r] = c
    return out

