"""Conflict checks. See README.md. O(n log n) sweeps."""
import heapq
from collections import defaultdict

from bookings import valid


def _by_room(bookings):
    rooms = defaultdict(list)
    for b in bookings:
        if valid(b):
            rooms[b.room].append(b)
    return rooms


def _pairs(items):
    """Pairs of intersecting intervals in one room."""
    items = sorted(items, key=lambda b: b.start)
    ends = []  # min-heap of end times of bookings that started earlier
    n = 0
    for b in items:
        while ends and ends[0] <= b.start:  # ended at or before this start: no clash
            heapq.heappop(ends)
        n += len(ends)
        heapq.heappush(ends, b.end)
    return n


def count_conflicts(bookings):
    return sum(_pairs(items) for items in _by_room(bookings).values())


def max_concurrent(bookings, room):
    events = []
    for b in bookings:
        if valid(b) and b.room == room:
            events.append((b.start, 1))
            events.append((b.end, -1))
    events.sort()  # at equal times the end (-1) sorts before the start (+1)
    best = cur = 0
    for _t, d in events:
        cur += d
        best = max(best, cur)
    return best


def conflicts_by_room(bookings):
    out = {}
    for room, items in _by_room(bookings).items():
        c = _pairs(items)
        if c:
            out[room] = c
    return out

