def parse(tag):
    core = tag.lstrip("v").split("+")[0]
    main, _, pre = core.partition("-")
    parts = main.split(".")
    return parts, pre


def sort_key(tag):
    parts, pre = parse(tag)
    return (parts, pre)


def compare(a, b):
    ka, kb = sort_key(a), sort_key(b)
    return (ka > kb) - (ka < kb)


def sort_versions(tags):
    return sorted(tags, key=sort_key)


def latest_release(tags):
    releases = [t for t in tags if "-" not in t]
    return sort_versions(releases)[-1] if releases else None

