"""Version tags. See README.md."""
import re

_NUM = r"(?:0|[1-9][0-9]*)"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_ID = r"[0-9A-Za-z-]+"
_SEMVER = re.compile(
    rf"^v?(?P<major>{_NUM})\.(?P<minor>{_NUM})\.(?P<patch>{_NUM})"
    rf"(?:-(?P<pre>{_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+(?P<build>{_ID}(?:\.{_ID})*))?$"
)


def parse(tag):
    """Return (major, minor, patch, prerelease identifiers tuple, build string or None)."""
    m = _SEMVER.match(tag)
    if not m:
        raise ValueError(f"not a semantic version: {tag!r}")
    pre = tuple(m.group("pre").split(".")) if m.group("pre") else ()
    return int(m.group("major")), int(m.group("minor")), int(m.group("patch")), pre, m.group("build")


def _pre_key(pre):
    # No pre-release sorts after any pre-release. Numeric ids sort before alphanumeric ones.
    if not pre:
        return (1,)
    return (0, tuple((0, int(p), "") if p.isdigit() else (1, 0, p) for p in pre))


def sort_key(tag):
    major, minor, patch, pre, _build = parse(tag)
    return (major, minor, patch, _pre_key(pre))


def compare(a, b):
    ka, kb = sort_key(a), sort_key(b)
    return (ka > kb) - (ka < kb)


def sort_versions(tags):
    return sorted(tags, key=sort_key)  # sorted() is stable


def latest_release(tags):
    releases = [t for t in tags if not parse(t)[3]]
    return max(releases, key=sort_key) if releases else None

