"""A small LRU cache with per-entry expiry. See README.md."""
from collections import OrderedDict

_MISSING = object()


class TTLCache:
    def __init__(self, maxsize, ttl, clock):
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        self.maxsize = maxsize
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, stored_at), least recently used first

    def _expired(self, stored_at, now):
        return now - stored_at >= self.ttl

    def _purge_expired(self):
        now = self.clock.now()
        for key in [k for k, (_v, t) in self._data.items() if self._expired(t, now)]:
            del self._data[key]

    def get(self, key, default=None):
        item = self._data.get(key, _MISSING)
        if item is _MISSING:
            return default
        value, stored_at = item
        if self._expired(stored_at, self.clock.now()):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def set(self, key, value):
        if key in self._data:
            del self._data[key]
        else:
            self._purge_expired()
            while len(self._data) >= self.maxsize:
                self._data.popitem(last=False)
        self._data[key] = (value, self.clock.now())

    def delete(self, key):
        self._data.pop(key, None)

    def __contains__(self, key):
        return self.get(key, _MISSING) is not _MISSING

    def __len__(self):
        self._purge_expired()
        return len(self._data)

