"""Web handler for ParcelPoint webhooks. See README.md."""
import json
import os

from webhook import verify_signature

ORDERS = {}


def mark(order_id, status, **extra):
    ORDERS.setdefault(order_id, {}).update(status=status, **extra)


def handle(headers, body):
    """Return (status_code, message)."""
    secret = os.environ.get("PARCEL_WEBHOOK_SECRET", "")
    try:
        ok = verify_signature(headers, body, secret)
    except NotImplementedError:
        return 501, "signature verification not available"
    except ValueError:
        return 400, "bad signature header"
    if not ok:
        return 401, "bad signature"
    event = headers.get("X-Parcel-Event", "")
    data = json.loads(body)
    if event == "shipment.delivered":
        mark(data["order_id"], "delivered", at=data["delivered_at"])
    elif event == "shipment.exception":
        mark(data["order_id"], "problem", reason=data.get("reason", ""))
    elif event in ("shipment.created", "shipment.in_transit"):
        mark(data["order_id"], event.split(".")[1])
    return 200, "ok"

