import time


def parse_signature_header(value):
    """'t=123,v2=abc,v2=def' -> (123, ['abc', 'def'])"""
    t = None
    sigs = []
    for part in value.split(","):
        key, _, val = part.strip().partition("=")
        if key == "t":
            t = int(val)
        elif key == "v2":
            sigs.append(val)
    if t is None or not sigs:
        raise ValueError("malformed signature header")
    return t, sigs


def timestamp_ok(t, now=None, tolerance=300):
    now = time.time() if now is None else now
    return abs(now - t) <= tolerance


