"""Run-length codec for log records. See SPEC.md and README.md."""


def compress(data):
    data = bytes(data)
    out = bytearray()
    i = 0
    while i < len(data):
        b = data[i]
        run = 1
        while i + run < len(data) and data[i + run] == b and run < 255:
            run += 1
        out.append(run)
        out.append(b)
        i += run
    return bytes(out)


def decompress(blob):
    blob = bytes(blob)
    if len(blob) % 2:
        raise ValueError("corrupt stream: odd length")
    out = bytearray()
    for i in range(0, len(blob), 2):
        count, b = blob[i], blob[i + 1]
        if count == 0:
            raise ValueError("corrupt stream: zero count")
        out.extend(bytes([b]) * count)
    return bytes(out)
